import{_ as s,l as r,o as e,c as i,v as n,p as l,x as o,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"预期管理与沟通","description":"","frontmatter":{"title":"预期管理与沟通","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/expectations-management.md","filePath":"econ/expectations-management.md","lastUpdated":1789023840000}'),c={name:"econ/expectations-management.md"};function m(B,a,h,A,_,f){const t=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=n('<h1 id="预期管理与沟通" tabindex="-1">预期管理与沟通 <a class="header-anchor" href="#预期管理与沟通" aria-label="Permalink to &quot;预期管理与沟通&quot;">​</a></h1><div class="epigraph"><p>工具利率受零下界或滞后约束时，路径的话与信息的话成为政策；听进去多少取决于更新率与信任。</p><footer>—— Woodford, Central-Bank Communication；Eggertsson and Woodford 对 ZLB 的前瞻指引；Gürkaynak, Sack and Swanson 的公告效应</footer></div><p><a href="/econ/survey-expectations">上一课</a>表明信念可测且常刚性。本课缺口是<strong>政策如何移动信念</strong>：沟通、前瞻指引。不重列 SPF 回归，不把资产负债表工具提前写完（QE 在后单元）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NK 里长期利率与预期路径进入总需求。ZLB 时当前隔夜利率动不了，承诺未来更久的宽松（Eggertsson–Woodford）是理论工具。实践：声明、点阵图、记者会。Gürkaynak–Sack–Swanson：公告窗内不只当前利率，路径因子也动。缺口是把高频识别课的「意外」当成沟通的产出，接到粘性信息/疏忽：同样的声明，更新者与未更新者分裂。</p><p><span class="marginnote">Eggertsson and Woodford, <em>Brookings</em> 2003。Gürkaynak, Sack and Swanson, <em>IJCB</em> 2005。Blinder 等沟通综述。Campbell, Evans, Fisher, Justiniano 的 Odyssean vs Delphic。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Odyssean：承诺改变未来反应函数。Delphic：揭示对经济的判断（信息效应）。调查与高频一起：若声明后家庭预期不动、市场价格动，疏忽或注意力配置在家庭侧。HANK：沟通若只动资产价格，财富效应走低 MPC；若动失业预期，走高 MPC。学习：体制转换声明要足够久才能进 PLM。</p>',8)),(e(),l(E,null,{default:o(()=>[p(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TALK%5B%22%E5%A3%B0%E6%98%8E%20%2F%20%E6%8C%87%E5%BC%95%22%5D%20--%3E%20ODY%5B%22%E6%94%B9%E5%8F%8D%E5%BA%94%E5%87%BD%E6%95%B0%22%5D%0A%20%20TALK%20--%3E%20DEL%5B%22%E6%8F%AD%E7%A4%BA%E5%88%A4%E6%96%AD%22%5D%0A%20%20ODY%20--%3E%20PATH%5B%22%E8%B7%AF%E5%BE%84%E9%A2%84%E6%9C%9F%22%5D%0A%20%20DEL%20--%3E%20INFO%5B%22%E4%BF%A1%E6%81%AF%E6%95%88%E5%BA%94%22%5D%0A%20%20LAM%5B%22%E8%B0%81%E6%9B%B4%E6%96%B0%22%5D%20--%3E%20EFF%5B%22%E8%B0%83%E6%9F%A5%E4%B8%8E%E4%BB%B7%E6%A0%BC%E7%9A%84%E5%88%86%E8%A3%82%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>可信度：时间不一致课已说明承诺难。沟通不能替代制度承诺，但能改变信息集。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是移动状态变量「信念」。在完全信息 RE，沟通要么是揭示私人信息，要么是承诺；没有「解释清楚」的独立通道。有粘性信息，重复沟通提高有效 \\(\\lambda\\)。有疏忽，简单、少噪声的规则节省容量。诊断性：生动情景可能过冲。因此沟通设计依赖本单元前几课选哪一套。</p><p>与财政：财政路径的沟通同样改李嘉图程度；HANK 里「未来税落在谁头上」的信念直接进乘数。</p><p><span class="marginnote">本课不写新闻稿文案技巧。也不把点阵图当成最优合约。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计最优词汇表。QE、TLTRO 是数量工具，后课资产负债表。通胀锚定下一课专写长期预期，本课是一般沟通装置。不进外汇微观结构。</p><p>后课默认：沟通分 Odyssean/Delphic；效力被更新率与信任打折。下一课：长期通胀预期如何被钉住或解钉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>前瞻指引与声明移动路径预期；ZLB 时更重要。</li><li>Odyssean vs Delphic 决定 IRF 符号。</li><li>家庭与市场价格分裂，用本单元的信息摩擦解释。</li><li>出处：Eggertsson and Woodford 2003；Gürkaynak, Sack and Swanson, <em>IJCB</em> 2005。</li></ul>',10))])}const D=s(c,[["render",m]]);export{k as __pageData,D as default};
